import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  // Estado de Autenticación
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [password, setPassword] = useState('');

  // Estados de navegación y datos
  const [pantalla, setPantalla] = useState('catalogo'); 
  const [productos, setProductos] = useState([]);
  const [ventasDelDia, setVentasDelDia] = useState(() => {
    const guardadas = localStorage.getItem('ventas_paisita');
    return guardadas ? JSON.parse(guardadas) : [];
  });

  // Fecha
  const [fechaHoy] = useState(() => new Date().toLocaleDateString('es-CO', { 
    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' 
  }));

  // Campos de formulario
  const [nombre, setNombre] = useState('');
  const [categoria, setCategoria] = useState('');
  const [imagenUrl, setImagenUrl] = useState('');
  const [precioCosto, setPrecioCosto] = useState('');
  const [impuesto, setImpuesto] = useState('19'); 
  const [precioVenta, setPrecioVenta] = useState('');
  const [stock, setStock] = useState('');

  // Efectos
  useEffect(() => {
    localStorage.setItem('ventas_paisita', JSON.stringify(ventasDelDia));
  }, [ventasDelDia]);

  useEffect(() => {
    if (isLoggedIn) obtenerInventarioBackend();
  }, [isLoggedIn]);

  // Funciones API
  const obtenerInventarioBackend = async () => {
    try {
      const respuesta = await fetch('http://localhost:8080/api/productos');
      if (respuesta.ok) {
        const datos = await respuesta.json();
        setProductos(datos);
      }
    } catch (error) { console.error("Error sincronizando:", error); }
  };

  const handleBorrarTodo = async () => {
    if (window.confirm("🚨 ¿Seguro que quieres borrar todo el inventario?")) {
      try {
        const respuesta = await fetch('http://localhost:8080/api/productos/vaciar', { method: 'DELETE' });
        if (respuesta.ok) {
          setProductos([]);
          setVentasDelDia([]);
          alert("Base de datos vaciada.");
        }
      } catch (error) { alert("Error de conexión."); }
    }
  };

  const cambiarStockManual = async (producto) => {
    const nuevoStockString = prompt(`Modificar stock de: ${producto.nombre}`, producto.stock);
    if (nuevoStockString === null) return;
    const nuevoStockNum = parseInt(nuevoStockString, 10);

    if (isNaN(nuevoStockNum) || nuevoStockNum < 0) return alert("Número inválido");

    const productoActualizado = { ...producto, stock: nuevoStockNum };

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(productoActualizado)
      });
      if (respuesta.ok) obtenerInventarioBackend();
    } catch (error) { alert("Error al actualizar stock."); }
  };

  const handleGuardar = async (e) => {
    e.preventDefault();
    const nuevoProducto = {
      nombre: nombre.trim(),
      categoria,
      imagenUrl: imagenUrl || 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c',
      precioCosto: parseFloat(precioCosto || 0),
      impuesto: parseFloat(impuesto || 0),
      precioVenta: parseFloat(precioVenta || 0),
      stock: parseInt(stock || 0)
    };

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(nuevoProducto)
      });
      if (respuesta.ok) {
        setNombre(''); setCategoria(''); setImagenUrl(''); setPrecioCosto(''); setPrecioVenta(''); setStock('');
        obtenerInventarioBackend();
        setPantalla('catalogo');
      } else {
        const err = await respuesta.text();
        alert("Error: " + err);
      }
    } catch (error) { alert("Error de conexión."); }
  };

  const registrarVenta = (producto) => {
    if (producto.stock <= 0) return alert("¡Agotado!");

    const cCosto = producto.precioCosto || 0;
    const cImpuesto = producto.impuesto || 0;
    const costoRealConIva = cCosto * (1 + cImpuesto / 100);
    const gananciaNeta = (producto.precioVenta || 0) - costoRealConIva;

    const nuevaVenta = {
      id: Date.now(),
      nombre: producto.nombre,
      precioVenta: producto.precioVenta || 0,
      gananciaNeta: gananciaNeta,
      hora: new Date().toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' })
    };

    setVentasDelDia([...ventasDelDia, nuevaVenta]);
    // Actualizar stock visual
    setProductos(productos.map(p => p.id === producto.id ? {...p, stock: p.stock - 1} : p));
  };

  const formatearMoneda = (v) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0 }).format(v || 0);

  // --- INTERFACES ---

  // LOGIN
  if (!isLoggedIn) {
    return (
      <div className="login-container" style={{display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', background: '#0F0906'}}>
        <form onSubmit={(e) => { e.preventDefault(); if (password === '123') setIsLoggedIn(true); else alert('Clave incorrecta'); }} style={{background: '#160E0A', padding: '40px', borderRadius: '20px', border: '1px solid #231710'}}>
          <h1 style={{color: '#E3CBB3', marginBottom: '20px'}}>Acceso El Paisita</h1>
          <input type="password" placeholder="Contraseña" className="form-input" value={password} onChange={(e) => setPassword(e.target.value)} required />
          <button type="submit" className="btn-submit" style={{marginTop: '15px'}}>Ingresar</button>
        </form>
      </div>
    );
  }

  // APP PRINCIPAL
  return (
    <div className="app-layout">
      <header className="app-header">
        <div className="header-brand"><h1>El Paisita UP</h1><p>📅 {fechaHoy}</p></div>
        <nav className="header-nav">
          <button className="nav-link" onClick={() => setPantalla('catalogo')}>📦 Catálogo</button>
          <button className="nav-link" onClick={() => setPantalla('formulario')}>➕ Ingresar</button>
          <button className="nav-link" onClick={() => setPantalla('reporte')}>📊 Caja</button>
          <button className="btn-nav-clear-database" onClick={handleBorrarTodo}>🔥 Reiniciar</button>
        </nav>
      </header>

      <main className="app-content">
        {pantalla === 'catalogo' && (
          <div className="grid-catalogo">
            {productos.map((prod) => (
              <div key={prod.id} className="card-producto">
                <div className="card-image-wrapper">
                   <img src={prod.imagenUrl} alt={prod.nombre} onError={(e)=>{e.target.src="https://images.unsplash.com/photo-1546069901-ba9599a7e63c"}} />
                </div>
                <div className="card-info">
                  <h3>{prod.nombre}</h3>
                  <div className="card-precios">
                    <div><span className="label-precio">Venta</span><span className="valor-venta">{formatearMoneda(prod.precioVenta)}</span></div>
                    <div><span className="label-precio">Costo</span><span className="valor-costo">{formatearMoneda(prod.precioCosto)}</span></div>
                  </div>
                  <p>Stock: {prod.stock}</p>
                  <button className="btn-vender-card" onClick={() => registrarVenta(prod)}>Vender</button>
                  <button className="btn-modificar-stock" onClick={() => cambiarStockManual(prod)}>✏️ Stock</button>
                </div>
              </div>
            ))}
          </div>
        )}

        {pantalla === 'formulario' && (
          <div className="form-container-centered">
            <div className="form-card">
              <form onSubmit={handleGuardar}>
                <input type="text" placeholder="Nombre" value={nombre} onChange={e => setNombre(e.target.value)} className="form-input" required />
                <input type="text" placeholder="Categoría" value={categoria} onChange={e => setCategoria(e.target.value)} className="form-input" />
                <input type="text" placeholder="Imagen URL" value={imagenUrl} onChange={e => setImagenUrl(e.target.value)} className="form-input" />
                <input type="number" placeholder="Costo" value={precioCosto} onChange={e => setPrecioCosto(e.target.value)} className="form-input" />
                <input type="number" placeholder="Venta" value={precioVenta} onChange={e => setPrecioVenta(e.target.value)} className="form-input" />
                <input type="number" placeholder="Stock" value={stock} onChange={e => setStock(e.target.value)} className="form-input" />
                <button type="submit" className="btn-submit">Guardar</button>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
